// backend/src/core/ai/patch/patch-apply.service.ts
import * as fs from 'fs';
import * as path from 'path';
import { fileReaderService } from '../files/file-reader.service';
import type { ApplyPatchResponse } from './patch-apply.types';

class PatchApplyService {
  private allowedRoot: string;
  private maxDiffChars: number;
  private backupDir: string;
  private blockedPaths: string[];

  constructor() {
    this.allowedRoot = process.env.AI_ALLOWED_ROOT || path.resolve(process.cwd());
    this.maxDiffChars = parseInt(process.env.AI_MAX_DIFF_CHARS || '100000', 10);
    this.backupDir = process.env.AI_PATCH_BACKUP_DIR || path.join(process.cwd(), '.ai-backups');
    this.blockedPaths = [
      '.env',
      'node_modules',
      'dist',
      'build',
      'uploads',
      'logs',
      '.git',
      '.env.local',
      '.env.production',
      '.env.development',
    ];
  }

  // Validar arquivo alvo (mesma lógica do file-reader)
  private validatePatchTarget(filePath: string): string {
    // Resolver path absoluto
    const resolvedPath = path.resolve(this.allowedRoot, filePath);
    
    // Garantir que está dentro da raiz permitida
    if (!resolvedPath.startsWith(path.resolve(this.allowedRoot))) {
      throw new Error('Path fora da raiz permitida');
    }

    // Verificar se está bloqueado
    const normalized = resolvedPath.toLowerCase();
    for (const blocked of this.blockedPaths) {
      if (normalized.includes(blocked.toLowerCase())) {
        throw new Error('Path bloqueado por segurança');
      }
    }

    // Verificar extensão .env
    if (normalized.endsWith('.env') || normalized.includes('.env.')) {
      throw new Error('Path bloqueado por segurança');
    }

    return resolvedPath;
  }

  // Criar backup do arquivo
  private createBackup(filePath: string): string {
    try {
      // Garantir que diretório de backup existe
      if (!fs.existsSync(this.backupDir)) {
        fs.mkdirSync(this.backupDir, { recursive: true });
      }

      // Ler conteúdo original
      const content = fs.readFileSync(filePath, 'utf-8');

      // Gerar nome do backup com timestamp
      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      const fileName = path.basename(filePath);
      const backupFileName = `${fileName}.${timestamp}.backup`;
      const backupPath = path.join(this.backupDir, backupFileName);

      // Escrever backup
      fs.writeFileSync(backupPath, content, 'utf-8');

      return backupPath;
    } catch (error: any) {
      throw new Error(`Erro ao criar backup: ${error.message}`);
    }
  }

  // Aplicar unified diff
  private applyUnifiedDiff(filePath: string, diff: string): void {
    try {
      // Ler conteúdo original
      const originalContent = fs.readFileSync(filePath, 'utf-8');
      const lines = originalContent.split('\n');

      // Parse do diff (formato simplificado)
      const diffLines = diff.split('\n');
      const newLines: string[] = [];
      let lineIndex = 0;
      let inHunk = false;

      for (const diffLine of diffLines) {
        if (diffLine.startsWith('@@')) {
          // Início de hunk
          inHunk = true;
          continue;
        }

        if (diffLine.startsWith('---') || diffLine.startsWith('+++')) {
          continue;
        }

        if (diffLine.startsWith(' ')) {
          // Linha inalterada
          if (lineIndex < lines.length) {
            newLines.push(lines[lineIndex]);
            lineIndex++;
          }
        } else if (diffLine.startsWith('-')) {
          // Linha removida
          lineIndex++;
        } else if (diffLine.startsWith('+')) {
          // Linha adicionada
          newLines.push(diffLine.substring(1));
        }
      }

      // Adicionar linhas restantes do original
      while (lineIndex < lines.length) {
        newLines.push(lines[lineIndex]);
        lineIndex++;
      }

      // Escrever arquivo modificado
      const newContent = newLines.join('\n');
      fs.writeFileSync(filePath, newContent, 'utf-8');
    } catch (error: any) {
      throw new Error(`Erro ao aplicar diff: ${error.message}`);
    }
  }

  // Aplicar patch com validações
  async applyPatch(
    filePath: string,
    diff: string,
    userId: string,
    tenantId: string
  ): Promise<ApplyPatchResponse> {
    const startTime = Date.now();

    try {
      // Validar tamanho do diff
      if (diff.length > this.maxDiffChars) {
        throw new Error(`Diff excede tamanho máximo de ${this.maxDiffChars} caracteres`);
      }

      // Validar arquivo alvo
      const resolvedPath = this.validatePatchTarget(filePath);

      // Verificar se arquivo existe
      if (!fs.existsSync(resolvedPath)) {
        throw new Error('Arquivo não encontrado');
      }

      // Verificar se é arquivo (não diretório)
      const stats = fs.statSync(resolvedPath);
      if (!stats.isFile()) {
        throw new Error('Path não é um arquivo');
      }

      // Criar backup
      const backupPath = this.createBackup(resolvedPath);

      // Aplicar diff
      this.applyUnifiedDiff(resolvedPath, diff);

      const appliedAt = new Date().toISOString();

      // Log (sem conteúdo do arquivo)
      console.info(
        `[PATCH] Aplicado - user: ${userId}, tenant: ${tenantId}, file: ${filePath}, diffSize: ${diff.length}, backup: ${backupPath}`
      );

      return {
        success: true,
        message: 'Patch aplicado com sucesso',
        backupPath,
        appliedAt,
      };
    } catch (error: any) {
      const duration = Date.now() - startTime;
      console.error(
        `[PATCH] Erro após ${duration}ms - user: ${userId}, tenant: ${tenantId}, file: ${filePath}, error: ${error.message}`
      );
      throw error;
    }
  }
}

export const patchApplyService = new PatchApplyService();















